import {useState} from "react";
import Counter from "./components/Counter";
export default function App(){const [count,setCount]=useState(()=>window.atoms.storage.get("count",0));function add(){const next=count+1;setCount(next);window.atoms.storage.set("count",next);}return <main><h1>计数器</h1><Counter value={count} add={add}/></main>}
